fn solve(input: Vec<char>) -> Vec<char> {
    // We know input.len() >= 3, input[1] is a space,
    // and input[0], input[2] ∈ {'H','D'}.
    let first = input[0];
    let third = input[2];

    if first == third {
        vec!['H', '\n']
    } else {
        vec!['D', '\n']
    }
}

